ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_any_29"] = {
{"s7_haul_generator_023","any",3,"reg=raider|tmp=predator|mood=grim|world=door,generator",{1,"Family on {street} had a generator running in the garage - you could hear it three blocks off",2,"Well, they'll hear everything else now, nice and quiet in the dark",3,"They had a little freezer on it, somebody's medicine in the door",1,"And now we got a generator, the gas is in the blue cans, don't mix 'em up"}},
{"s7_haul_dog_food_024","any",2,"reg=raider|mood=funny|world=road",{1,"Station wagon full of dog food - nothing else, just forty-pound sacks",2,"They have a dog?",1,"Didn't see one",2,"We ought to get a dog, something to bark when they come up the road at night",1,"We got Rooster for that"}},
{"s7_haul_church_ladies_025","any",3,"reg=raider|day=3,120|mood=fear|world=building",{1,"Church pantry in Rosewood, four old ladies in there, and not a one of 'em ran",2,"Just stood there praying at us, holding hands in a circle",3,"Praying for us, not at us, there's a difference",2,"Felt like at, felt like they had our names written down somewhere",1,"Load the canned goods, I'm not talking about it"}},
{"s7_haul_tampon_box_026","any",2,"reg=raider,prison|mood=funny|world=building",{1,"Know where that man kept his bullets? In a box of tampons under the bathroom sink",2,"Smart",1,"It is smart, I walked right past it twice",2,"So from now on we check every box of tampons in Knox County",1,"From now on you check, I've done my part"}},
{"s7_haul_siphon_027","any",2,"reg=raider|hour=16,5|mood=funny|world=vehicle",{1,"Got about eight gallons off the church bus before it started coming up rusty",2,"Who sucked on the hose?",1,"Petey",2,"That why he's been burping gasoline all afternoon?",1,"Nobody light a smoke anywhere near Petey tonight"}},
{"s7_haul_deputy_revolver_028","any",3,"reg=raider,prison|day=1,40|mood=fear|world=door",{1,"Found a service revolver in a shoebox, house had a deputy's hat on the rack by the door",2,"Where's the deputy?",1,"Wife said he went on shift Friday night and never came home",3,"That's his gun, man, you don't carry a dead deputy's gun",1,"It's a gun, it don't know who owned it",3,"It knows"}},
{"s7_haul_lookout_share_029","any",3,"reg=raider|tmp=predator|hour=8,20|mood=angry|world=vehicle,door",{1,"Lookout gets a half share, that's how it's always been",2,"I stood on that water tank four hours in the sun - the backs of my ears are blistered",3,"You didn't kick no doors",2,"If I don't see the truck coming, you don't have any doors left to kick",1,"Half share - put some mud on your ears"}},
{"s7_haul_empty_tank_030","any",2,"reg=raider|tmp=predator|mood=funny|world=vehicle",{1,"Man tossed me his keys so fast I knew something was off",2,"What was off?",1,"Tank - bone dry, he'd been sleeping in that car at the rest stop three days",2,"So you robbed a man of his bedroom",1,"And he thanked me for letting him keep the pillow"}},
{"s7_haul_punch_card_031","any",2,"reg=raider|tmp=predator|day=7,200|mood=funny",{1,"I remember that fella by the feed store. We'd got him the week before too",2,"The one with the big ears?",1,"Saw us coming and started emptying his pockets, didn't even wait for us to ask",2,"You called him a regular. Said we ought to give him a punch card",1,"I said tenth one's free. He didn't laugh"}},
{"s7_haul_nurse_bag_032","any",3,"reg=raider,prison|mood=calm",{1,"Nurse bag out of the house by the clinic - what's all this?",2,"That's gauze - that's tape, that's, hell, I don't know what that is",3,"Don't swallow anything you can't pronounce",2,"I can't pronounce any of it",1,"Then it all goes to trade, somebody out there finished school"}},
{"s7_haul_fireworks_033","any",3,"reg=raider|mood=fear|world=vehicle",{1,"Found a trunk full of bottle rockets and Roman candles - leftover from the Fourth",2,"Set 'em off at the far end of town and pull the dead off the grocery - that's a plan",3,"Or pull every one of 'em in six miles straight to us",1,"It's a good idea",3,"It's a loud idea, those are two different kinds of idea"}},
{"s7_haul_fair_share_mutter_034","any",1,"reg=raider|tmp=predator|hour=4,9|mood=angry|world=building",{1,"Split it fair, he says - real fair",1,"He takes the deer rifle and the camp stove, and I get a can opener - a can opener and no cans",1,"Keep on, one of these nights I'll be fair to myself and gone by sunup"}},
{"s7_haul_piggy_bank_035","any",2,"reg=raider,prison|mood=funny|world=water",{1,"Busted the piggy bank, nine dollars and forty cents, all quarters and dimes",2,"Payphone money",1,"Payphone at the bait shop's been dead since Saturday",2,"Then it's skipping-stone money, chuck 'em in the river",1,"Me throw money in a river? That's when you'll know it's really over"}},
{"s7_haul_sister_voice_036","any",3,"reg=raider|tmp=predator,seasoned|mood=sad",{1,"Please, mister, I just want to get to my sister's - just to my sister's, okay? Hahaha",2,"He did talk like that - real soft",3,"He said his wife was already gone, his boy too",1,"So what?",3,"So nothing, do the voice again - go on",1,"Nah, it's not funny when you ask for it"}},
{"s7_haul_gold_bite_037","any",2,"reg=raider,prison|tmp=predator|mood=funny",{1,"Which one of these is real gold?",2,"Bite it, real gold, your teeth leave a mark",1,"I'm not biting nothing that came off a woman's neck",2,"Biting's how this whole mess started anyhow",1,"Exactly my point, you bite it"}},
{"s7_haul_beagle_038","any",3,"reg=raider|mood=warm|world=vehicle",{1,"Took the family's beagle along with the truck, didn't mean to, it jumped in the cab",2,"And now it sleeps on Wade",3,"It does not sleep on me, it sleeps near me",2,"It's on your lap right this second",3,"His name's Biscuit, says so on his tag - leave him be"}},
{"s7_haul_cb_chatter_039","any",2,"reg=raider|tmp=predator|hour=20,4|mood=calm",{1,"That CB we took off the salesman is the best thing we got all week - listen to nineteen",2,"Anybody saying where they're at?",1,"Some old boy keeps telling his wife he's at the Irvington grain elevator - every hour, on the hour",2,"Then he's at the grain elevator",1,"Every hour on the hour, like he's asking for company"}},
{"s7_haul_wax_bottle_040","any",3,"reg=raider|mood=fear|world=building",{1,"Whose is the good bottle? The one with the red wax on top",2,"Boss's",1,"Says who? I found it in that cellar",3,"Says the last guy who opened it - go ask him",1,"Where's he at?",3,"Exactly"}},
{"s7_haul_hunter_calm_041","any",2,"reg=raider,prison|mood=fear",{1,"That hunter took it real calm, handed over the knives handle first",2,"Polite",1,"Then he looked at every one of us - slow, like he was memorizing",2,"He's one old man with no knives",1,"Said he knew every holler from here to Ekron, said it friendly, too"}},
{"s7_haul_granola_042","any",2,"reg=raider|mood=funny|world=vehicle",{1,"Couple in the painted van, hair down to here, both of 'em - got a dream catcher and five pounds of granola",2,"That's all you got off them?",1,"And a baggie of something green - don't get excited, it's oregano",2,"You smoked it, didn't you",1,"Not all of it"}},
{"s7_haul_bunker_043","any",3,"reg=raider|tmp=predator|day=3,120|mood=funny|world=building",{1,"Guy had a whole bunker dug under his shed - Army rations stacked to the ceiling",2,"Tried one, tastes like a wet wallet",3,"Twenty years he spent getting ready for this, and we walked in the first week",1,"Nobody gets ready for the fella who shows up after"}},
{"s7_haul_sweet_tea_044","any",2,"reg=raider|tmp=predator,seasoned|mood=sad",{1,"Old lady made us sweet tea - before, poured it in the good glasses",2,"She knew what we were there for",1,"Course she did, she still put a lemon in mine",2,"Did you drink it?",1,"Drank it, then we cleaned out her pantry - what was I gonna do, leave the lemon?"}},
{"s7_haul_birdshot_debt_045","any",2,"reg=raider,prison|tmp=predator|mood=funny",{1,"You owe me four shells from Tuesday",2,"Paid you back Thursday",1,"With birdshot, birdshot ain't a payment, birdshot's an insult",2,"Shoots, don't it?",1,"It tickles, Randy, it tickles people"}},
{"s7_haul_taped_pistol_046","any",3,"reg=raider|mood=grim|world=building",{1,"Pistol taped under the kitchen table, right under where he was sitting with his hands up",2,"Boone had him - Boone was right on top of him",3,"Two cans of chili and a sleeve of saltines, that's what that house was worth",1,"Somebody's got to tell Boone's girl",2,"You tell her, you searched the kitchen"}},
{"s7_haul_watch_mutter_047","any",1,"reg=raider,prison|hour=4,11|mood=grim",{1,"Man's watch still runs, wound it this morning",1,"Initials on the back - R.D.L., and a date from nineteen seventy-one",1,"Keeps good time, too, whatever time's good for anymore"}},
{"s7_haul_wedding_dress_048","any",3,"reg=raider|day=2,120|mood=sad|world=vehicle",{1,"Why'd you take the wedding dress?",2,"Crystal wanted it",3,"I did not want it, I said it was pretty",2,"Out here that's the same thing",3,"Still in the plastic from the cleaners, ticket says ready for pickup July twelfth",1,"Well, nobody's picking it up"}},
{"s7_haul_peppermint_049","any",4,"reg=raider|tmp=predator|mood=funny",{1,"Everything on the tarp, pockets too, Jimmy - pockets",2,"It's lint",3,"Lint and a peppermint",4,"That's my peppermint from the bank in West Point, I've had it since before",1,"Then it goes in the pile - nobody's special",4,"It's a peppermint, man"}},
{"s7_haul_family_bible_050","any",2,"reg=raider|tmp=seasoned,predator|mood=sad",{1,"You took the Bible?",2,"Big one had the family names in the front - Births, weddings, back to eighteen-something",1,"What do you want with that?",2,"Nothing, somebody ought to keep the list is all",1,"We're the reason that list is getting longer",2,"Then I'll write 'em in"}},
{"s8_club_loud_pipes_001","any",3,"reg=club|mood=funny",{1,"Twenty years I told every citizen who'd listen that loud pipes save lives",2,"And now?",1,"Now I'm stuffing steel wool up my baffles like a church deacon on a moped",3,"Heard you coming anyway, so did about forty of them"}},
{"s8_club_stale_gas_002","any",2,"reg=club|day=60,3650|mood=grim|world=water",{1,"Smell that? Carb's full of varnish, gas out of that station tank has gone sour",2,"Three, four months, that's all gas keeps without stabilizer",1,"So the whole county come with an expiration date",2,"The bikes do, county can rot at its own pace",1,"Every marina, every farm shed, somebody in this county winterized something"}},
{"s8_club_prospect_pump_003","any",3,"reg=club|mood=grim",{1,"Prospect - how much gas did you pull off that motor home?",2,"Six gallons, sir",3,"Don't call him sir, he works for a living - or he did",1,"Six gallons, and it took you four hours?",2,"There was one in the driver's seat, still buckled in, kept reaching for me the whole time I was under there",1,"So you had company, four hours is still four hours"}},
{"s8_club_road_captain_tank_004","any",2,"reg=club|mood=calm",{1,"Run to Brandenburg is thirty-one miles, every bike makes it on what's in the tank, no stops",2,"Moon's peanut tank won't do thirty-one, not the way he rides",1,"Then Moon rides behind me and quits twisting his wrist like he's mad at it",2,"He is mad at it, he's mad at everything",1,"Strap a gallon can to his sissy bar, and don't tell him it's mine"}},
{"s8_club_funeral_run_005","any",3,"reg=club|mood=sad|world=trees",{1,"When Gravel's daddy passed we had sixty bikes behind the hearse - stopped traffic clear to the cemetery",2,"Law even blocked the intersections for us, only time they ever did us a favor",3,"Who rode behind Gravel?",1,"Me - just me - Idled real low so nothing came",3,"Where'd you put him?",1,"Under the pecan tree out back, his kickstand's the marker"}},
{"s8_club_church_vote_006","any",4,"reg=club|day=3,200|mood=warm",{1,"Church is in session, motion is, that family from the Riverside trailer park stays in the back room",2,"Bylaws say no citizens in the clubhouse, it's on the first page",3,"Bylaws say dues are twenty a month, too - you paid dues lately?",4,"They got a little girl, she's been drawing on the pool table with the cue chalk",2,"I vote no",1,"Fine - hands, three to one - somebody go tell her she can keep the chalk"}},
{"s8_club_chrome_morning_007","any",2,"reg=club|mood=funny",{1,"Why are you polishing my chrome, kid? Nobody's looking at it",2,"You told me polish it every morning",1,"I told you that in June",2,"You never told me to stop",1,"Yeah, get the spokes too, if I go I'm going clean"}},
{"s8_club_cut_from_ditch_008","any",2,"reg=club|mood=grim|world=fence,water",{1,"You went back for his cut?",2,"Colors don't get left in a ditch, that's the oldest rule we got",1,"He was still in that ditch, Dutch, he was still moving",2,"Yeah, took both hands to get it off him",1,"Where's the cut now?",2,"Washed it in the creek, it's drying on the fence - nobody touch it"}},
{"s8_club_kicker_mutter_009","any",1,"reg=club|mood=angry",{1,"Come on, come on, you stubborn old iron bitch",1,"Timing's right - Plug's hot, gas is gas, you just don't want to",1,"Fine, I'll push you downhill, like it's nineteen seventy-nine and I'm broke again"}},
{"s8_club_airstrip_fuel_010","any",3,"reg=club|day=10,3650|mood=calm",{1,"There's a crop duster strip past Ekron, hundred octane in a tank up on stilts",2,"Airplane gas'll run a bike?",3,"Runs it hot, and the lead in it'll foul your plugs by Christmas",1,"Christmas is a long way off, and I'm on fumes today",2,"Who's guarding it?",1,"A windsock, maybe the pilot, if he stayed"}},
{"s8_club_prospect_nickname_011","any",3,"reg=club|mood=funny",{1,"What are we calling the new prospect?",2,"Gallon",3,"Because he's big?",2,"Because that's how much gas he poured on my boots his first day",3,"And the one before him?",2,"Lunch",1,"That ain't funny, that boy tried hard"}},
{"s8_club_gavel_line_012","any",3,"reg=club|day=2,120|mood=angry",{1,"Bylaws say the VP takes the gavel",2,"VP's in Louisville, or whatever's walking around in his boots is",3,"Then it goes to sergeant-at-arms - that's me",1,"Says the page, or says you?",3,"Says the page - go get the book if you want, I'll hold your beer",2,"Book's back at the old clubhouse with the rest of what we left"}},
{"s8_club_old_lady_pistol_013","any",2,"reg=club|mood=sad",{1,"Skeeter's old lady asked me for a gun",2,"Give her one",1,"She's never shot one - Skeeter wouldn't let her near 'em",2,"Skeeter ain't here to have an opinion - take her out back with the thirty-eight",1,"She held it like it was his - real careful, like she was gonna get in trouble for touching it"}},
{"s8_club_bait_shop_colors_014","any",3,"reg=club|mood=grim",{1,"Brandenburg boys are camped at the bait shop, their colors, our side of the county",2,"Ten years ago we'd already be out there with bats",3,"Ten years ago there was more than nine of us - how many they got?",1,"Five, one's got his arm in a sling",3,"Send the prospect with a jar - tell 'em the county line moved, it's wherever the dead ain't"}},
{"s8_club_church_van_015","any",2,"reg=club|mood=funny|world=vehicle,door",{1,"Prez wants everybody in the church van till we find more gas",2,"A motorcycle club, in a van",1,"A van with a sliding door that says Faith Baptist Youth Ministry down the side",2,"I'll walk",1,"You'll ride in the van, you'll sit in the back, and you'll hold the felt banner"}},
{"s8_club_roof_singer_016","any",2,"reg=club|hour=21,5|mood=fear|world=building,rooftop",{1,"Prospect's been on the roof since dark - you hear him?",2,"Hear him what?",1,"Singing - real low, keeping himself awake",2,"Tell him cut it out - sound carries",1,"Went up to, he's shaking so hard the rifle's knocking on the shingles - I let him sing"}},
{"s8_club_new_book_017","any",3,"reg=club|hour=16,5|mood=grim",{1,"New rules, and they ain't in the book, nobody rides after dark - nobody opens a throttle inside a town limit",2,"Nobody ever rode alone, either - that's already in there, ain't it?",1,"I ain't done, you coast into a town - you push out of it",3,"Push? Push a seven-hundred-pound dresser up Main Street?",1,"Push it or leave it, the bike don't bite, everything else does"}},
{"s8_club_dues_mutter_018","any",1,"reg=club|mood=sad",{1,"Dues - Skeeter, paid through August, moon, owes May, June and July",1,"Wishbone, paid, always paid on the first - cash in an envelope with his own name spelled wrong",1,"Marking him paid through the rest of it, ain't like anybody's coming to audit"}},
{"s8_club_early_rocker_019","any",3,"reg=club|day=7,300|mood=warm",{1,"Prospect's got eleven months left before he's even eligible",2,"We buried four full patches this month, rules like that are for a club with spares",3,"He ain't done a run, he ain't done a year",1,"He carried Stitch out of that pharmacy on his back - that's a year",2,"Get the rocker out of the drawer, somebody find a needle that ain't bent"}},
{"s8_club_tiny_carb_020","any",2,"reg=club|mood=grim",{1,"Tiny always said bury him with his bike",2,"Tiny's bike has a rebuilt carb and a battery that holds a charge",1,"I know what it has",2,"So Tiny gets the pipes, he loved them pipes, the carb goes on yours",1,"He'd have called that fair, he'd have called you a thief first - then fair"}},
{"s8_club_laundromat_pie_021","any",3,"reg=club|day=3,90|mood=funny|world=road",{1,"Lady who runs the laundromat in Muldraugh knocked on our door - wants us to look after her street",2,"The same lady called the law on us every Fourth of July for fifteen years?",1,"Same one, brought a pie",3,"What kind of pie?",1,"Why in the world would that matter?",3,"Matters to me, it tells you if we're forgiven or just needed"}},
{"s8_club_pilgrim_name_022","any",2,"reg=club|mood=funny",{1,"How'd you get the name Pilgrim?",2,"First run I ever went on, I took the wrong exit and was gone three days",1,"Three days?",2,"Came home with a sunburn, a speeding ticket from Tennessee, and a name",1,"Well, don't get lost on this one",2,"Getting lost I'm good at, it's finding the way back that got hard"}},
{"s8_club_panhead_cow_023","any",3,"reg=club|day=5,3650|mood=angry",{1,"Dutch traded his panhead to the farmer out by March Ridge",2,"For what?",1,"A deer rifle, three hundred rounds, and a milk cow",3,"A cow, he traded a nineteen fifty-two panhead for a cow",1,"She gives milk, that panhead never gave nothing but oil on the garage floor",3,"Tell him I'm never speaking to him again, after I get a glass"}},
{"s8_club_president_cards_024","any",1,"reg=club|role=biker_boss|mood=grim",{1,"Forty-one patches in this chapter the first of July, I signed every one of their cards",1,"Nine now, nine that answer when I bang on the table",1,"Old man who started this club said the president brings everybody home - never said what to do with the ones who come home wrong"}},
{"s8_club_kicker_soft_025","any",2,"reg=club|mood=funny",{1,"Battery on the dresser's flat again",2,"That's why God made kick starters, electric start made your whole generation soft",1,"Generation? I'm fifty-three years old",2,"Soft for fifty-three, then, swing a leg"}},
{"s8_club_bar_fingers_026","any",3,"reg=club|hour=18,2|mood=funny",{1,"Prospect's tending bar tonight, two fingers a man, and he's got the smallest fingers in Kentucky",2,"That's why we put him back there",3,"Let me see your hands, kid - good Lord, them are raccoon hands",1,"Pour, and quit sticking your pinky out, that ain't a finger we're counting"}},
{"s8_club_oakie_cut_027","any",3,"reg=club|day=2,60|mood=sad",{1,"Where's Oakie?",2,"Took his bike before light, left his cut folded on his bunk",3,"Left the cut, so he ain't on club business",2,"His mama's in Louisville, he asked every night for a week, every night we told him no",1,"Put the cut in his locker, nobody sleeps on his bunk"}},
{"s8_club_single_file_028","any",2,"reg=club|mood=funny|world=road",{1,"Staggered formation's done, you hit one of them at forty, you and the man beside you both go down",2,"Single file, then",1,"Single file, road captain up front - prospect in the back",2,"Why the prospect in the back?",1,"Tradition",2,"That ain't a tradition",1,"It is as of right now"}},
{"s8_club_lefty_gate_029","any",3,"reg=club|mood=angry",{1,"Lefty's at the gate - wants in",2,"Lefty's out bad, we blacked out his back tattoo ourselves in eighty-eight",3,"He's got two cases of motor oil and a woman with a hole in her leg",2,"Out bad is out bad",1,"He brought motor oil, Crowbar",2,"Woman comes in - Lefty sits outside the gate on his oil till I'm done thinking"}},
{"s8_club_prospect_list_030","any",1,"reg=club|mood=sad",{1,"Wash the bikes, siphon the gas - stand the watch - dig the holes, yes sir, no sir",1,"Eleven more months, and I get a patch to wear in a county with nobody left to see it",1,"Stupid, I still want it - I want it so bad"}},
{"s8_club_sticky_lifter_031","any",3,"reg=club|day=3,200|mood=warm",{1,"Hush - y'all hear that?",2,"That's a shovelhead - Loping like it's got a sticky lifter",3,"Only one man rides around on a lifter that bad for four years out of pure spite",1,"Moon's been gone six days",3,"Open the gate, open the damn gate!"}},
{"s8_club_bungee_can_032","any",2,"reg=club|mood=funny",{1,"You owe me four gallons from the Rosewood run",2,"I owe you two, you spilled two",1,"It spilled because you hit a pothole with my can bungeed to your fender",2,"Potholes are the county's business - take it up with the county",1,"County's out on the Dixie Highway with its jaw hanging off - I'm taking it up with you"}},
{"s8_club_leather_sleeve_033","any",2,"reg=club|day=0,70|hour=11,18|mood=calm",{1,"Hundred degrees out and you're still in the leather",2,"One of 'em bit this sleeve Thursday, chewed and chewed and couldn't get through",1,"I'll wear mine, soon as I quit sweating out of my eyeballs",2,"Sweat's cheap - arms ain't"}},
{"s8_club_tuesday_call_034","any",2,"reg=club|day=5,120|hour=20,23|mood=sad",{1,"Mother chapter in Louisville ain't come back on the CB in nine days",2,"CB don't reach Louisville from here, it never did",1,"I know that",2,"Then why do you keep calling?",1,"Tuesday nights at nine, we called in - twelve years - it's Tuesday"}},
{"s8_club_rigid_kid_035","any",3,"reg=club|mood=warm",{1,"Crowbar carried that little boy all the way from Irvington on the back of his rigid",2,"No shocks, forty miles? That kid's gotta be black and blue",3,"Fell asleep holding Crowbar's belt, so Crowbar rode the whole way at thirty-five",2,"Crowbar ain't done thirty-five in his life",3,"He's gonna deny it - don't you bring it up"}},
{"s8_club_fryer_oil_036","any",2,"reg=club|day=20,3650|mood=funny|world=vehicle,water",{1,"We're out of twenty-fifty, prospect wants to try the fryer oil from the fish shack",2,"In my engine?",1,"Says the tractor boys used to do it in a pinch",2,"Then every dead one from here to the river follows me around like I'm a hush puppy"}},
{"s8_club_texas_rocker_037","any",3,"reg=club|day=1,60|mood=calm|world=road",{1,"Fella at the gate's wearing a Texas bottom rocker",2,"What's a Texas boy doing in Knox County?",3,"Passing through to see his sister - Army shut the road right behind him",1,"Says he's a nomad, says he'll pull his weight",2,"Nomads don't pull nobody's weight, that's why they're nomads",3,"He's got a toolbox on that bike the size of a coffin",2,"Well, let's see him pull some weight"}},
{"s8_club_stitch_parking_lot_038","any",2,"reg=club|mood=grim|world=road",{1,"Who took care of Stitch?",2,"Me, he told me at the bar, second night - if it's ever me, it's you",1,"He meant it?",2,"We were both drunk, both of us laughing",1,"Alright",2,"Did it out in the parking lot - not inside, he liked this place too much"}},
{"s8_club_stuck_horn_039","any",3,"reg=club|mood=fear",{1,"Whose horn is that?",2,"Pilgrim's, wire shorted when he hit the rail crossing - been blowing ever since",3,"Tell him pull the fuse!",2,"He's trying, he's riding and trying - with about thirty of them behind him like a parade",1,"Nobody opens this gate, wave him past the water tower, he knows what to do"}},
{"s8_club_duck_hunter_040","any",2,"reg=club|mood=calm",{1,"Prospect - who taught you to shoot?",2,"My granddad - ducks, mostly",1,"These things are slower than ducks and they don't fly - why are you missing?",2,"Ducks don't look at you",1,"Fair, put the front sight on the forehead and don't go looking for eyes"}},
{"s8_club_members_only_041","any",2,"reg=club|hour=4,11|mood=funny",{1,"Sign on our front door still says members only, no exceptions",2,"Nobody told the sick ones",1,"Three of 'em out there this morning pawing at it",2,"Well, two of those were members"}},
{"s8_club_moped_042","any",3,"reg=club|day=10,3650|mood=funny",{1,"Prospect found a moped behind the pharmacy - quiet as a sewing machine, hundred miles to the gallon",2,"No",3,"Hear him out",2,"No member of this club is gonna be seen on a moped",1,"Seen by who?",2,"By me, I'll see it - I'll know"}},
{"s8_club_lug_wrench_043","any",2,"reg=club|day=2,200|mood=sad",{1,"Where's the gavel?",2,"On the table at the old clubhouse, nobody grabbed it when we ran",1,"Twenty-six years that gavel came to church",2,"Here - lug wrench",1,"Church is open, somebody write it in the minutes, we use a lug wrench now"}},
{"s8_club_hoss_sleepwalk_044","any",2,"reg=club|mood=fear",{1,"Passed out on the pool table and woke up with Hoss chewing on my arm, hahaha!",2,"Hoss sleepwalks, he's done that since eighty-five",1,"Yeah, that's what I figured - it didn't break the skin - mostly",2,"Let me see it",1,"It's fine - where'd the beer go?"}},
{"s8_club_pruitt_fence_045","any",3,"reg=club|day=5,3650|mood=calm|world=fence",{1,"Old Pruitt's got a five-hundred-gallon gas tank on a stand behind his barn",2,"Pruitt hates us, called us hoodlums at the feed store in front of God and everybody",3,"Pruitt's got a busted fence and dead ones in his pasture eating his calves",1,"So we fix his fence, and he forgets the word hoodlum",2,"For five hundred gallons I'll be a hoodlum who fixes fences"}},
{"s8_club_kill_headlight_046","any",2,"reg=club|hour=21,4|mood=fear|world=road",{1,"Kill the headlight",2,"It's pitch black, I can't see the road",1,"Everything in that bean field can see you - kill it",2,"Then I'm riding by the moon",1,"Moon's what we got - go slow and keep your front tire on the center line"}},
{"s8_club_hubcap_test_047","any",3,"reg=club|day=3,3650|mood=funny|world=vehicle,window",{1,"My last prospect night, they made me steal the hubcaps off a trooper's cruiser while he ate breakfast",2,"So what's this kid's gonna be?",3,"Trooper cruiser's nosed in the ditch by the county line - trooper's still buckled in it",1,"Hubcaps, kid - all four - take a tire iron and don't lean on the window"}},
{"s8_club_matchbook_points_048","any",2,"reg=club|mood=sad",{1,"Wrench always set my points with a matchbook cover, said a feeler gauge was for people with money",2,"You remember the gap?",1,"No, I just remember watching him do it",2,"Nineteen thousandths, a matchbook's close enough - hold the light still"}},
{"s8_club_green_sky_049","any",2,"reg=club|mood=funny|world=storm",{1,"Storm's coming up the valley, whole sky's gone green",2,"Tarp the bikes",1,"And us?",2,"The bikes are worth something"}},
{"s8_club_gallons_mutter_050","any",1,"reg=club|day=14,3650|mood=grim",{1,"Three cans in the shed, eleven gallons, give or take - two in the dresser, one in the rigid",1,"That's Brandenburg and half the way back",1,"Half a ride back is a walk, better pick who walks before they pick for me"}},
{"s8_club_helmet_law_051","any",2,"reg=club|mood=funny",{1,"Commonwealth of Kentucky says I got to wear a helmet",2,"Commonwealth of Kentucky ain't answering the phone",1,"That's what I said, then one of 'em grabbed me by the hair at the Rosewood exit",2,"So you're wearing the helmet",1,"I'm wearing the helmet - don't you ever tell Frankfort it won"}},
{"s8_club_chaplain_words_052","any",3,"reg=club|mood=sad",{1,"Somebody say words over Buck",2,"Chaplain says the words, that's his whole job",3,"I ain't a real chaplain, I got the title because I owned a Bible and could read",1,"Then read something",3,"Buck owed me forty dollars, that's what I got - Buck, you owed me forty dollars, and I forgive it",2,"That's good, that's real good"}},
{"s8_club_poker_run_053","any",3,"reg=club|day=7,3650|mood=funny",{1,"We ought to do a poker run",2,"To where? Every stop's a dead gas station",1,"So those are the stops, draw a card at each one - best hand wins",3,"Wins what? There ain't a prize left in this county",1,"Best hand sits out the next gas run",2,"Now that's a pot worth playing for"}},
{"s8_club_wall_patch_054","any",2,"reg=club|mood=grim|world=water",{1,"That Brandenburg patch on our wall, took it off a man in a bar fight in eighty-six",2,"Pride of the clubhouse",1,"Saw him Monday, the man it came off of, walking circles down by the river landing",2,"You put him down?",1,"Yeah, figured I owed him that much - leave the patch up"}},
{"s8_club_beer_test_055","any",3,"reg=club|day=3,3650|mood=angry",{1,"Prospect - walk to the gas station at the bottom of the hill and bring me back a case of beer",2,"Now? There's a mess of 'em in that lot",1,"That's why they call it a test",3,"Sit down, Prospect, you want a beer, you walk down there yourself",1,"Since when do we coddle prospects?",3,"Since we're down to one"}},
{"s8_club_shed_can_056","any",4,"reg=club|mood=angry|world=generator",{1,"Somebody's been bleeding the shed can a little every night",2,"Prospect?",3,"Prospect sleeps against that shed, he'd have heard",4,"It was me, a gallon a night for my sister's generator, her baby's on a breathing machine",1,"You could've asked",4,"You'd have said no",1,"Probably, now I don't get to say nothing"}},
{"s8_club_bald_tire_057","any",2,"reg=club|day=20,3650|mood=calm|world=vehicle",{1,"Rear tire's showing cords",2,"Bike shop in Muldraugh had a whole rack of tires",1,"Bike shop's got a showroom full of dead folks standing between the new bikes - I looked in the glass",2,"So we go in the back, one of us makes noise out front",1,"And I bet I know which one of us"}},
{"s8_club_knox_gate_wave_058","any",3,"reg=club|day=1,60|mood=funny",{1,"Soldiers at the Fort Knox gate waved at me Tuesday",2,"Waved you through?",1,"No, waved like, keep rolling, citizen, before we find out if you're sick",3,"Twenty years that base turned bikers away at the gate - now they turn away everybody",2,"Equal treatment, only took the end of the world"}},
{"s8_club_colors_target_059","any",3,"reg=club|day=7,3650|mood=grim",{1,"Folks see the colors and start shooting, they think it's us been robbing houses",2,"Some of it is us",3,"Not in the colors",1,"Maybe we ride without 'em, just a while",3,"You take that patch off, you better have a real good reason, and a new club",2,"Nobody's taking it off, we just ride slower past the church folks"}},
{"s8_club_rally_quilt_060","any",2,"reg=club|mood=sad",{1,"What's that wrapped around you?",2,"Darlene's quilt, made out of run T-shirts, every rally from eighty to ninety-two",1,"I remember that square, the eagle one - that was the year it rained the whole weekend",2,"She never got the border done, needle's still stuck in the corner"}},
{"s8_club_little_earl_061","any",3,"reg=club|mood=funny",{1,"New kid says his daddy rode with the Louisville chapter",2,"What was his daddy's name?",1,"Says Big Earl",3,"Never was a Big Earl, there was a Little Earl, and he died in eighty-one with no kids - bragged about it",2,"So the kid's a liar",1,"Kid's a liar who can rebuild a carburetor in the dark - I'll allow the lie"}},
{"s8_club_memorial_ink_062","any",2,"reg=club|day=5,3650|mood=sad|world=road",{1,"Hold still - you want his road name or his Christian name?",2,"Road name, nobody knew the other one",1,"That's the fourth name on this arm since the ninth",2,"Leave room"}},
{"s8_club_two_brakes_063","any",3,"reg=club|mood=angry",{1,"Why are you on Wishbone's bike?",2,"Because mine's got no front brake and his has two good ones",3,"You don't ride another man's scoot, you know that since you were a prospect",2,"Wishbone ain't coming back for it",1,"Rule don't say a word about coming back",2,"Then I'll push it to church and y'all can vote on my brakes"}},
{"s8_club_sergeant_mutter_064","any",1,"reg=club|mood=grim",{1,"Sergeant-at-arms - keep order at the table - carry the piece, break up the fights",1,"Nothing in there about brothers in a gravel lot, one at a time",1,"Should've read them bylaws closer - heh, should've read 'em at all"}},
{"s8_club_indiana_bridge_065","any",3,"reg=club|day=1,40|mood=calm|world=cars,water,road",{1,"Brandenburg bridge, straight over the river into Indiana - twenty minutes and we're out",2,"Army's got the bridge, sandbags, trucks, wire, all of it",1,"How close did you get?",2,"Close enough to hear turn around on a bullhorn, then one round into the road",3,"Kid in a Guard helmet yelling it, I used to fix his daddy's truck",1,"Then the bridge goes back on the map as a maybe"}},
{"s8_club_jukebox_b7_066","any",2,"reg=club|hour=19,1|mood=sad|world=generator",{1,"Somebody hook the jukebox to the generator",2,"Generator's for the freezer and the radio",1,"One song - B-seven, it was Tiny's",2,"I know which one it was",1,"One song",2,"Low - real low, then the cord goes back on the freezer"}},
{"s8_club_prez_owes_067","any",2,"reg=club|mood=funny",{1,"Prez says he owes you, Prospect",2,"He don't owe me nothing",1,"He does, and he hates owing, so he's gonna make your life hell till it's square",2,"How do I make it square?",1,"Die, or save him again, I'd go with again"}},
{"s8_club_slate_door_068","any",4,"reg=club|mood=calm|world=door",{1,"Front door's steel - back door's the problem",2,"Park the dresser against it",3,"Dresser's the only bike that starts on the first kick - it sits at the gate facing out",4,"Then the pool table goes against the back door",1,"That's eight hundred pounds of slate",4,"Good, then it stays where we put it"}},
{"s8_club_sherry_gate_069","any",3,"reg=club|day=1,60|mood=funny",{1,"Hatchet, your ex-wife's at the gate",2,"Which one?",1,"The one who set your bike on fire",2,"Sherry - how's she look?",3,"Scared, got both her boys and a pump shotgun",2,"Let her in, hide the lighter fluid"}},
{"s8_club_river_road_fourth_070","any",2,"reg=club|mood=sad|world=water,road",{1,"Fourth of July we rode the river road to Brandenburg for the fireworks - forty bikes, sun going down on the water",2,"Moon's boy on the back of his bike holding a sparkler",1,"Sparks all down his arm, he didn't care one bit",2,"That was a Sunday"}},
{"s8_club_teeth_investment_071","any",3,"reg=club|mood=funny",{1,"When I prospected, Dutch smacked me upside the head every time I talked at the table",2,"You still talk too much at the table",1,"So how come nobody's allowed to smack the new kid?",3,"New kid's the only one of us with all his teeth - we're protecting the investment"}},
{"s8_club_stolen_vests_072","any",3,"reg=club|day=7,3650|mood=angry",{1,"Man in Rosewood says a bunch wearing our colors robbed the Methodist church",2,"We ain't set foot in Rosewood in two weeks",3,"Somebody took the vests off our dead at the Muldraugh warehouse - that's who",1,"Wearing our brothers' names to rob old women",2,"Then we find 'em, and they give the vests back - one way or the other",3,"The other"}},
{"s8_club_leftover_bolts_073","any",2,"reg=club|mood=funny",{1,"What's that left over on the rag?",2,"Three bolts and a spring",1,"Where do they go?",2,"I was hoping you'd tell me",1,"Tear it down again, from the top - this time lay every piece out in a row, in order"}},
{"s8_club_buckshot_bottle_074","any",4,"reg=club|hour=16,5|mood=angry|world=fence",{1,"Remember Buckshot falling asleep drunk on watch?",2,"He'd buried his boy that Wednesday",3,"I knew. Didn't make me less scared about who was keeping watch",4,"He needed somebody sitting with him, not just somebody taking a bottle",1,"None of us wanted to be the one to knock",4,"I wish I'd done it sooner"}},
{"s8_club_dentist_floss_075","any",3,"reg=club|day=5,3650|mood=funny|world=vehicle",{1,"That dentist we took in fixed my charging system",2,"A dentist",1,"Said an engine's just a big mouth with a lot of little teeth - straight face",3,"What's he want for it?",1,"Wants every one of us to floss, he's dead serious about it"}},
{"s8_club_mother_oath_076","any",3,"reg=club|day=3,40|mood=grim|world=water",{1,"Mother chapter's in the West End, we swore it - any brother calls, we ride",2,"Nobody called",1,"Because nobody can",3,"Louisville's burning from the river to the airport, I saw the glow from the bluff Friday night",1,"So we sit here",3,"We sit here, and if one of them comes down 31W on a bike, we ride out to meet him - that's what's left of the oath"}},
{"s8_club_big_d_paint_077","any",2,"reg=club|mood=sad|world=building",{1,"Paint's still tacky - don't touch the tank till morning",2,"Letters look good",1,"Made the D bigger than the rest, he wrote his D's big on everything - school papers, the garage wall",2,"Big D's, every one of 'em"}},
{"s8_club_feed_store_runner_078","any",3,"reg=club|mood=angry|world=building",{1,"Prospect ran at the feed store, left Hoss with his back against the wall",2,"Hoss made it",1,"No thanks to the kid, kid's out at the gate, crying",3,"Old rule is a prospect who runs loses his teeth and his bike",2,"Kid don't have a bike, he's got a ten-speed",3,"Then Hoss decides, hoss is the one who had the wall at his back"}},
{"s8_club_baptist_door_079","any",3,"reg=club|day=5,3650|mood=warm|world=door",{1,"Preacher at Rosewood Baptist asked if we'd stand guard Sunday during service",2,"Us - at church",3,"I ain't been inside a church since my mamaw's funeral",1,"You don't go in, you stand by the door with a bat",3,"That's where I stood at mamaw's funeral too"}},
{"s8_club_reserve_mutter_080","any",1,"reg=club|mood=calm|world=rain",{1,"Easy, girl, easy - keep her under three grand and nobody hears us",1,"Eleven miles on reserve, you did twelve once - Louisville, in the rain - you remember",1,"Do it one more time and I'll find you real gas - premium, I swear to God, premium"}},
{"s8_club_overpass_rocker_081","any",2,"reg=club|day=5,3650|mood=grim",{1,"One in the crowd by the overpass is wearing a Kentucky bottom rocker",2,"Ours?",1,"Ours, I can't see the front, can't see the name tag",2,"Then we go find out",1,"Or we don't, and he stays whoever you want him to be"}},
{"s8_club_forty_five_082","any",2,"reg=club|day=10,3650|mood=funny|world=vehicle",{1,"At forty-five that bike does forty-eight to the gallon, at seventy it does thirty-one",2,"Nobody ever bought a motorcycle to ride forty-five",1,"Nobody bought one to push, either - pick",2,"Forty-five, but I'm gonna look fast doing it"}},
{"s8_club_dartboard_minutes_083","any",3,"reg=club|day=3,120|mood=sad|world=building",{1,"Reading minutes from last church - old business, stitch wants the dartboard moved off the bathroom wall",2,"Move on",1,"Stitch ain't... Motion's withdrawn, I guess",3,"Move the dartboard - for Stitch"}},
{"s8_club_beans_half_084","any",3,"reg=club|mood=warm",{1,"Patches eat first, prospect eats what's left",2,"There ain't nothing left, there's a pot with a spoon standing in it",3,"Here, half of mine - don't make a thing out of it",1,"That ain't how it goes",3,"It goes how I say with my own beans"}},
{"s8_club_water_tower_cut_085","any",4,"reg=club|day=7,3650|hour=16,5|mood=angry",{1,"They hung Chigger's cut off the Riverside water tower, hung it right where we'd see",2,"So we ride tonight",3,"On what? We got gas for one run, the farm for food, or Riverside to bleed",4,"Chigger'd take the food run",2,"Chigger ain't voting",1,"He just did - food run - Riverside keeps till we got the gas to hate 'em with"}},
{"s8_club_dog_hangaround_086","any",3,"reg=club|day=5,3650|mood=warm|world=fence",{1,"That dog's slept by the bikes every night since he wandered in",2,"Barks when they get near the fence, better than the prospect",3,"Put a patch on him",1,"He ain't done a year",3,"He's done more nights on that fence than you have",2,"Hangaround, he can be a hangaround - that's as far as I go"}},
{"s8_club_south_dakota_map_087","any",2,"reg=club|mood=sad",{1,"We were taking the whole chapter out to the big rally in South Dakota next August - first time ever",2,"Moon had the route drawn on a gas station map - every stop circled in red",1,"Still got it?",2,"In his saddlebag - folded wrong"}},
{"s8_club_quarry_lure_088","any",3,"reg=club|mood=fear",{1,"Somebody's gotta go rev a bike out by the quarry and pull that crowd off the clubhouse",2,"And outrun 'em after",3,"I'll go, mine's the loudest, been proud of that ten years",1,"Only if she fires on the first kick",3,"She always fires on the first kick - for me"}},
{"s8_club_deacon_saying_089","any",2,"reg=club|mood=calm",{1,"Old Deacon said you don't fight for the patch, you fight for the man beside you, and the patch takes care of itself",2,"Deacon said a lot of things, half of 'em after a fifth",1,"That one he said sober, at his daughter's wedding",2,"Well, man beside me is you - find me some gas and I'll fight for you"}},
{"s8_club_sponsor_door_090","any",3,"reg=club|mood=grim|world=door",{1,"Prospect's bit, right under the thumb, he's asking for Hoss",2,"Why Hoss?",3,"Hoss sponsored him, stood up for him at the table",1,"Sponsor sees to his prospect, that's in the book too",2,"Hoss is in the back room with the door shut - ten minutes now, not a sound"}},
{"s8_club_screen_door_091","any",2,"reg=club|mood=sad|world=door",{1,"We rode right past my house on the Rosewood run",2,"You want to go back and stop?",1,"Don't need to, screen door was hanging open, wind banging it",2,"Maybe they got out",1,"Maybe, she never did remember to latch it"}},
{"s8_club_ten_gallon_patch_092","any",3,"reg=club|day=14,3650|mood=funny",{1,"Heard the Irvington club's patching in anybody who shows up with ten gallons",2,"Ten gallons for a patch",3,"Ten gallons is a lot of gas right now",2,"My patch cost me two years, a wired jaw, and my first marriage",3,"Yeah, but did you have ten gallons?"}},
{"s8_club_frankfort_letter_093","any",2,"reg=club|mood=sad",{1,"What are you writing, Prospect?",2,"Letter to my mama in Frankfort",1,"Mail ain't running",2,"I know, I want her to know I found some people, in case it ever does"}},
{"s8_club_pipes_potatoes_094","any",2,"reg=club|day=10,3650|mood=funny|world=building",{1,"Traded my spare set of drag pipes for a sack of potatoes",2,"What's a farmer want with drag pipes?",1,"He's running one through the roof of his smokehouse",2,"Them pipes took first place at the bike show in Bowling Green",1,"Now they'll take first place for smoked ham in Ekron"}},
{"s8_club_gavel_rehearsal_095","any",1,"reg=club|day=3,200|mood=grim",{1,"Brothers, the table's mine now - no, brothers, I never asked for this - no",1,"Deacon's gone, anybody's got a problem with me, take it outside, that's more like him",1,"Take it outside - heh, like there's anyplace that ain't outside anymore"}},
{"s8_club_queen_boot_096","any",3,"reg=club|hour=19,2|mood=funny",{1,"That's the third full house you drew tonight, Pilgrim",2,"Clean living",3,"Clean living's got a queen of hearts down in his boot",2,"That's a spare, from the other deck",1,"Gas can goes back to Hatchet, and so does the boot"}},
{"s8_club_heart_pills_097","any",3,"reg=club|day=10,3650|mood=sad",{1,"Prez is out of his heart pills",2,"How long?",3,"Four days, he's been cutting 'em in half since the county went dark and not telling nobody",1,"Pharmacy in West Point had shelves of 'em",2,"Then we ride, nobody tell him why - he'll order us to stay"}},
{"s8_club_gravel_rash_098","any",2,"reg=club|mood=funny",{1,"Laid it down in the gravel by the church - Skinned from my elbow to my wrist",2,"Hold still, this is gonna sting",1,"What is that?",2,"Corn liquor, only thing we got that's cleaner than you",1,"Pour it on, then - don't you pour all of it"}},
{"s8_club_hand_signals_099","any",3,"reg=club|hour=4,8|mood=calm|world=road",{1,"Kickstands up in ten, nobody talks on the road",2,"Hand signals only?",1,"Fist means stop - Point down means a hole, two fingers at your eyes means them",3,"What's the one for I need to pee?",1,"Ain't one, we left it off on purpose"}},
{"s8_club_last_church_mutter_100","any",1,"reg=club|day=60,3650|mood=sad",{1,"Minutes, church called to order by me, members present, me",1,"Old business, none - new business, the gas is gone - motion to keep the club going anyhow",1,"Seconded - by me - motion carries"}},
{"s8_gang_country_dark_101","any",3,"reg=gang|hour=21,4|mood=fear",{1,"Man, it's too dark out here - where the streetlights at?",2,"County don't do streetlights, county does crickets",3,"Something just walked through that corn",1,"Something like a cow, or something like them?",3,"I don't know what a cow sounds like, man, I'm from Portland"}},
{"s8_gang_hold_the_block_102","any",3,"reg=gang|day=1,60|mood=grim|world=vehicle",{1,"Big Mike told us get the shorties out the city - said he'd hold the block",2,"Hold it against what? The whole West End was on fire",1,"Said somebody gotta be there when folks come back",3,"Nobody's coming back to Broadway",1,"So who calls it now?",2,"Whoever's still breathing and holding the van keys - that's me"}},
